contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 stage) public payable {
        require(stage <= 1, "stage must be 0 or 1");

        bool reverted;
        uint storedBlock;

        if (stage == 0) {
            // No lockInGuess call: caller has no active guess, settle must revert.
            try c.settle() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            // Fund the contract so we can lock a guess, then settle in the same block.
            require(address(this).balance >= 1 ether, "need 1 ether to lock a guess");
            c.lockInGuess{value: 1 ether}(bytes32(0));

            try c.settle() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // In the same block, the guess block equals block.number + 1,
            // so block.number is not greater than it and settle must revert.
            assert(reverted);

            // The failed settle must not have cleared the active guess.
            storedBlock = rec_getBlock();
            assert(storedBlock != 0);
        }
    }

    function rec_getBlock() internal view returns (uint) {
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("guesses(address)", address(this)));
        require(ok, "getter call failed");
        return abi.decode(data, (uint));
    }

    receive() external payable {}
}

