            );
            require(ok, "failed to read guess block");
            (guessBlock, ) = abi.decode(data, (uint, bytes32));
        }

        // We need to advance the block number so that settle can succeed.
        // Since we can't directly change block.number, we rely on the context
        // that a later block has a greater number. But in a single transaction
        // the block number is fixed. To make settle work, we must ensure the
