contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash) public payable {
        // No precondition on c's state: fresh deployment has no lock for this test contract.
        // Only require enough balance so the call can be made with exactly 1 ether.
        require(address(this).balance >= 1 ether);

        bool reverted;
        try c.lockInGuess{value: 1 ether}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the deciding call, the public getter for guesses must reflect the outcome:
        // a successful lock records the sender's guess; a revert leaves it unchanged.
        (uint blockNum, bytes32 recordedGuess) = c.guesses(address(this));

        if (reverted) {
            assert(blockNum == 0 && recordedGuess == bytes32(0));
        } else {
            assert(recordedGuess == hash && blockNum != 0);
        }
    }

    receive() external payable {}
}

