contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash) public payable {
        require(address(this).balance >= 2 ether);

        c.lockInGuess{value: 1 ether}(hash);

        bool revertedTooEarly;
        try c.settle() {
            revertedTooEarly = false;
        } catch {
            revertedTooEarly = true;
        }

        uint unlock = block.number + 1;
        while (block.number <= unlock) {
            // advance one block at a time using an empty self-call
            (bool ok, ) = address(this).call("");
            require(ok);
        }

        bool revertedAfterUnlock;
        try c.settle() {
            revertedAfterUnlock = false;
        } catch {
            revertedAfterUnlock = true;
        }

        assert(revertedTooEarly && !revertedAfterUnlock);
    }

    receive() external payable {}
}

