contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 hash, uint amount, bool alreadyGuessed) public payable {
        require(address(this).balance >= amount);
        // Optionally set up an existing guess (for the alreadyGuessed condition)
        if (alreadyGuessed) {
            require(address(this).balance >= 1 ether);
            c.lockInGuess{value: amount}(hash);
        }
        // Read the before-state of the caller's guess via public getter if available
        // Since C does not expose a public getter on guesses, we cannot read it.
        // Instead, we test the lockInGuess behavior by calling it and checking revert conditions.
        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call succeeds iff the caller had no existing guess AND exactly 1 ether was sent.
        // Since we cannot read whether a guess existed before the call directly, we use the alreadyGuessed flag
        // to represent that precondition.
        // The rule: reverted should be false exactly when !alreadyGuessed && amount == 1 ether.
        assert(reverted == (alreadyGuessed || amount != 1 ether));
    }

    receive() external payable {}
}

